\label{thm:main-intro}
For~every $m\geqslant1$,
\begin{align*}
  P_m\text{ is a~shuffle square}
  \quad\Longleftrightarrow\quad
  m\in\operatorname{EPK}\setminus\{4,8\}.
\end{align*}

\label{thm:C3-parity}
Let $w\in\mathcal{C}^3$ and $|w|>16$. Then $w$ is a~shuffle square if and only if
\begin{align*}
  |w|_{\textcolor{purple!69!black}{\mathtt{1}}}\equiv |w|_{\textcolor{purple!69!black}{\mathtt{2}}}\equiv0\pmod2.
\end{align*}
The~bound~$16$ is sharp. Moreover, exactly~$34$ nonempty even-Parikh $C^3$-words are not shuffle squares, and all of~them are smooth.

\label{def:factor}
Let $u,w\in\mathcal{A}^*$.  The~word~$u$ is a~\emph{factor} of~$w$ if there are words $x,y\in\mathcal{A}^*$ such that
\begin{align*}
  w=xuy.
\end{align*}
Thus a~factor is a~contiguous subword.  It is a~\emph{prefix} when one can take $x=\varepsilon$, and a~\emph{suffix} when one can take $y=\varepsilon$.  Empty factors, prefixes, and suffixes are allowed unless ``nonempty'' is stated. For~example,
\begin{align*}
  \textcolor{purple!69!black}{\mathtt{122112}}=(\textcolor{purple!69!black}{\mathtt{12}})(\textcolor{purple!69!black}{\mathtt{211}})(\textcolor{purple!69!black}{\mathtt{2}}),
\end{align*}
so $\textcolor{purple!69!black}{\mathtt{211}}$ is a~factor.  The~word $\textcolor{purple!69!black}{\mathtt{122}}$ is a~prefix, while $\textcolor{purple!69!black}{\mathtt{112}}$ is a~suffix.

\label{def:reversal}
For~a~word $w=\textcolor{purple!69!black}{\mathtt{w}}_1\textcolor{purple!69!black}{\mathtt{w}}_2\cdots \textcolor{purple!69!black}{\mathtt{w}}_n$, its \emph{reversal} is the~word
\begin{align*}
  \operatorname{rev}(w):=\textcolor{purple!69!black}{\mathtt{w}}_n\textcolor{purple!69!black}{\mathtt{w}}_{n-1}\cdots \textcolor{purple!69!black}{\mathtt{w}}_1.
\end{align*}
Its \emph{binary complement} $\overline w$ is obtained by~interchanging $\textcolor{purple!69!black}{\mathtt{1}}$ and~$\textcolor{purple!69!black}{\mathtt{2}}$ in~every position.  We put $\operatorname{rev}(\varepsilon)=\overline\varepsilon=\varepsilon$.  For~example,
\begin{align*}
  \operatorname{rev}(\textcolor{purple!69!black}{\mathtt{12211}})=\textcolor{purple!69!black}{\mathtt{11221}},
  \qquad \overline{\textcolor{purple!69!black}{\mathtt{12211}}}=\textcolor{purple!69!black}{\mathtt{21122}}.
\end{align*}
Directly from~the~definition, $\operatorname{rev}(\operatorname{rev}(w))=w$ and $\operatorname{rev}(uv)=\operatorname{rev}(v)\operatorname{rev}(u)$.

\label{def:shuffle-square}
A~nonempty word $w\in\mathcal{A}^*$ is a~\emph{shuffle square} if there is a~partition
\begin{align*}
  \{1,\ldots,|w|\}=I\mathbin{\dot\cup}J
\end{align*}
such that $w|_I=w|_J$.  The~common word is called a~\emph{shuffle-square root} of~$w$.  Either set $I$ or $J$ is called a~\emph{support} of~one copy of~the~root.

\label{ex:first-decomposition}
Consider
\begin{align*}
  P_{16}=\textcolor{purple!69!black}{\mathtt{1221121221221121}}.
\end{align*}

Take $I=\{1,2,3,4,6,7,11,13\}$ and $J=\{5,8,9,10,12,14,15,16\}$. Then $P_{16}|_I=P_{16}|_J=\textcolor{purple!69!black}{\mathtt{12212121}}$. Thus $P_{16}$ is a~shuffle square.

\label{rem:residual-pruning}
Suppose $|w|=n$ and a~residual~$q$ is present after $i$ letters.  Every subsequent transition changes $|q|$ by~exactly one.  Therefore a~state with~$|q|>n-i$ cannot reach~$\varepsilon$ in~the~remaining $n-i$ steps and may be discarded without changing whether the~final empty state is reachable.

All finite verifications below use precisely this logically lossless pruning together with~the~necessary parity test from~Lemma~\ref{lem:even-necessary}.

\label{def:Ck}
For~an~integer $k\geqslant0$, let
\begin{align*}
  \mathcal{C}^k=\{w\in\mathcal{A}^*:D^j(w)\text{ is defined for~every }1\leqslant j\leqslant k\}.
\end{align*}
We call a~member of~$\mathcal{C}^k$ a~\emph{$\mathcal{C}^k$-word}. Thus $\mathcal{C}^0=\mathcal{A}^*$, and the~convention $D(\varepsilon)=\varepsilon$ allows a~derivative tower which reaches~$\varepsilon$ early to~be continued indefinitely.

\label{def:smooth}
A~finite binary word~$w$ is \emph{smooth}, or a~$\mathcal{C}^\infty$-word, if its finite derivatives remain defined until the~empty word is reached. Equivalently,
\begin{align*}
  w\in\mathcal{C}^\infty:=\bigcap_{k\geqslant0}\mathcal{C}^k.
\end{align*}

\label{lem:smooth-closure}
For~every $k\geqslant0$ the~following statements hold.
\begin{enumerate}[(i)]
\item Every factor of~a~$\mathcal{C}^k$-word is a~$\mathcal{C}^k$-word.
\item A~word~$w$ belongs to~$\mathcal{C}^k$ if and only if its reversal $\operatorname{rev}(w)$ belongs to~$\mathcal{C}^k$, and whenever $D(w)$ is defined,
\begin{align*}
  D(\operatorname{rev}(w))=\operatorname{rev}(D(w)).
\end{align*}
\item A~word~$w$ belongs to~$\mathcal{C}^k$ if and only if its complement $\overline w$ belongs to~$\mathcal{C}^k$.
\end{enumerate}
The~corresponding three assertions also hold for~smooth words.

Let $u$ be a~factor of~a~word~$w$ whose derivative is defined.  Every run of~$u$, except possibly its first and last runs, is a~complete run of~$w$. If an~endpoint run of~$u$ is only a~one-letter fragment of~a~run of~$w$, its run length~$1$ is deleted by~$D$.  If an~endpoint run survives in~$D(u)$, then it has length~$2$ and is therefore a~complete run of~$w$.  Moreover, a~one-letter endpoint run of~$w$ cannot survive as~an~interior run of~$u$. It follows that
\begin{align}\label{eq:factor-derivative}
  D(u)\text{ is a~factor of~}D(w),
\end{align}
with~the~empty word allowed.  Iterating \eqref{eq:factor-derivative} proves~(i).

Reversal reverses the~list of~run lengths, while the~two boundary deletions in~Definition~\ref{def:derivative} are symmetric. Hence $D(\operatorname{rev}(w))=\operatorname{rev}(D(w))$, and iteration proves~(ii). Complementation does not change any run length, so $D(\overline w)=D(w)$ whenever the~derivative is defined. This proves~(iii). Since every smooth word belongs to~$\mathcal{C}^k$ for~every~$k$, and its derivative tower reaches~$\varepsilon$, the~same arguments give the~final assertion.

Let $u$ be a~finite factor of~a~smooth right-infinite word~$X$.  Its endpoint runs may be truncated pieces of~runs of~$X$, and Definition~\ref{def:derivative} deletes exactly the~ambiguous one-letter endpoint run lengths.  All surviving run lengths are complete.  Hence
\begin{align*}
  D(u)\text{ is a~factor of~}\Delta(X),
\end{align*}
with~the~empty word allowed.  Applying the~same argument successively gives
\begin{align*}
  D^j(u)\text{ is a~factor of~}\Delta^j(X)
\end{align*}
for~every~$j$ for~which $D^j(u)$ is nonempty.  Since all letters in~every $\Delta^j(X)$ belong to~$\{\textcolor{purple!69!black}{\mathtt{1}},\textcolor{purple!69!black}{\mathtt{2}}\}$, each derivative is defined.  A~nonempty finite derivative is strictly shorter than its input, so the~process reaches $\varepsilon$.  Thus $u$ is finite smooth.

\label{prop:even-gap}
The~set~$\operatorname{EPK}$ is infinite.  If $e<e'$ are consecutive elements of~$\operatorname{EPK}$, then
\begin{align*}
  e'-e\in\{2,4,6,8\}.
\end{align*}

\label{ex:even-prefixes}
The~successive differences of~the~initial terms in~\eqref{eq:EPKterms} are
\begin{align*}
  4,8,4,4,4,6,2,4,4,4,8,4,4,2,2,4,4,4,\ldots.
\end{align*}

Listing~\ref{lst:bad-prefix-tree}, with $k=3$ and $L=24$, gives precisely
\begin{align*}
(|\mathcal{B}_n^{(3)}|)_{n=0}^{24}
={}&(1,2,2,4,4,6,6,6,6,8,10,10,10,14,14,18,10,10,8,10,4,4,4,4,0).
\end{align*}
Thus the~complete tree has only~$175$ nodes and $\mathcal{B}_{24}^{(3)}=\varnothing$, proving the~prefix assertion. The~suffix assertion follows by~reversal, using Lemmas~\ref{lem:smooth-closure}(ii) and~\ref{lem:closure-shuffle}(ii).

For~sharpness, put
\begin{align}\label{eq:A23}
 A=\textcolor{purple!69!black}{\mathtt{12211211212212211211221}}.
\end{align}
The~last nonempty level is
\begin{align}\label{eq:bad23}
 \mathcal{B}_{23}^{(3)}
 =\{A,\operatorname{rev}(A),\overline A,\overline{\operatorname{rev}(A)}\}.
\end{align}
All four words are smooth, so the~local constant~$24$ cannot be decreased even in~the~smooth subclass.

Necessity is Lemma~\ref{lem:even-necessary}. For~sufficiency, use strong induction over the~even lengths. The~twelve lengths $18,20,\ldots,40$ are the~complete base in~Table~\ref{tab:C3-base}. If $|w|\geqslant42$, the~length-$24$ suffix of~$w$ belongs to~$\mathcal{C}^3$ by Lemma~\ref{lem:smooth-closure}(i). Lemma~\ref{lem:C3-local} gives it a~nonempty shuffle-square suffix~$U$ with $2\leqslant|U|\leqslant24$. Write $w=vU$. Both $w$ and~$U$ have even Parikh vector, hence so does~$v$. Moreover, $v\in\mathcal{C}^3$ and $|v|\geqslant18$. The~induction hypothesis makes $v$ a~shuffle square, and Lemma~\ref{lem:closure-shuffle}(i) then makes $w=vU$ a~shuffle square.

For~sharpness, consider
\begin{align}\label{eq:C16}
 C=\textcolor{purple!69!black}{\mathtt{1221121121221221}}.
\end{align}
It has eight occurrences of~each letter and derivative tower
\begin{align*}
 C\mapsto\textcolor{purple!69!black}{\mathtt{221211212}}\mapsto\textcolor{purple!69!black}{\mathtt{211211}}
  \mapsto\textcolor{purple!69!black}{\mathtt{212}}\mapsto\textcolor{purple!69!black}{\mathtt{1}}\mapsto\varepsilon,
\end{align*}
so it is smooth. The~exact residual test rejects~$C$. In~fact, $C\in\mathcal{B}_{16}^{(3)}$. Hence the~threshold cannot be lowered.

Finally, the~complete calculation at~the~even lengths at~most~$16$ gives exactly~$34$ nonempty even-Parikh $C^3$-words rejected by~the~recognizer. Their distribution is
\begin{align}\label{eq:C3-exception-counts}
 (n,e_n)=(4,2),(8,6),(10,4),(12,10),(14,4),(16,8).
\end{align}
Direct iteration of~the~finite derivative verifies that every one of these~$34$ words is smooth.

Recurrence~\eqref{eq:Ck-bad-tree}, Listings~\ref{lst:bad-prefix-tree} and~\ref{lst:parity-levels}, the~full bad-tree vector, and Table~\ref{tab:C3-base} give a~finite verification for every exhaustive step used in~this proof.

Listing~\ref{lst:bad-prefix-tree}, with $k=2$ and $L=40$, gives
\begin{align*}
(|\mathcal{B}_n^{(2)}|)_{n=0}^{40}
={}&(1,2,2,4,4,6,6,6,6,8,10,14,12,18,18,22,16,20,20,26,22,\\
&30,26,32,28,38,38,50,40,52,36,46,36,44,22,26,10,10,8,8,0).
\end{align*}
Thus the~complete tree has~$823$ nodes and $\mathcal{B}_{40}^{(2)}=\varnothing$. This proves the~prefix assertion, and reversal gives the~suffix assertion. Finally,
\begin{align}\label{eq:C2-bad39}
 \textcolor{purple!69!black}{\mathtt{122112112122122122112112112122122122112}}=\textcolor{purple!69!black}{\mathtt{122}}(\textcolor{purple!69!black}{\mathtt{112}})^2(\textcolor{purple!69!black}{\mathtt{122}})^3(\textcolor{purple!69!black}{\mathtt{112}})^3(\textcolor{purple!69!black}{\mathtt{122}})^3\textcolor{purple!69!black}{\mathtt{112}}
\end{align}
belongs to~$\mathcal{B}_{39}^{(2)}$, proving optimality.

The~displayed complete vector, together with recurrence~\eqref{eq:Ck-bad-tree} and Listing~\ref{lst:bad-prefix-tree}, is a~finite reproducible verification for this local lemma.

\label{cor:C2-factorization}
Every finite $C^2$-word~$w$ has a~factorization
\begin{align*}
 w=S_1S_2\cdots S_k r,
\end{align*}
obtained by~successively removing the~shortest nonempty shuffle-square prefix, where every $S_i$ is a~$C^2$ shuffle square satisfying $2\leqslant|S_i|\leqslant40$, and the~terminal remainder satisfies $r\in\mathcal{C}^2$ and $|r|\leqslant39$. If $k\geqslant1$, then $S_1\cdots S_k$ is a~shuffle square. Both the~remainder bound~$39$ and the~block bound~$40$ are sharp.

Apply recurrence~\eqref{eq:Ck-bad-tree} with $k=1$. The~complete level sizes through the~onset of~periodicity are
\begin{align}\label{eq:C1-bad-counts}
(|\mathcal{B}_n^{(1)}|)_{n=0}^{42}
={}&(1,2,2,4,4,6,6,10,10,14,16,26,26,36,38,56,52,72,76,104,\\ \nonumber
&108,150,146,202,186,244,242,316,298,372,346,432,390,454,\\ \nonumber
&418,470,422,430,422,422,422,422,422).
\end{align}
The~nonzero counts of~even-Parikh words in these levels are given in Table~\ref{tab:C1-even-bad}. They sum to~$230$, and the~last occurs at length~$34$.

\begin{table}[ht]
\centering
\caption{Nonempty even-Parikh $C^1$-words with no nonempty shuffle-square prefix}
\label{tab:C1-even-bad}
\small
\begin{tabular}{@{}rr@{\qquad}rr@{\qquad}rr@{}}
\toprule
$n$ & number & $n$ & number & $n$ & number\\
\midrule
 4 & 2 & 16 & 10 & 26 & 28\\
 8 & 4 & 18 & 14 & 28 & 38\\
10 & 2 & 20 & 24 & 30 & 20\\
12 & 8 & 22 & 18 & 32 & 24\\
14 & 6 & 24 & 28 & 34 & 4\\
\midrule
\multicolumn{6}{c}{$\displaystyle\text{total}=230$}\\
\bottomrule
\end{tabular}
\end{table}

It remains to~prove that no later even-Parikh level can reappear. For a~residual~$q$ and a~word~$z$ whose first run starts after a~run boundary, write
\begin{align*}
 q\xrightarrow{z}r
\end{align*}
when the~unpruned run-capacity transitions of Listing~\ref{lst:run-test}, initialized at~$q$, can finish at~$r$. The~finite calculation partitions the~$422$ words in $\mathcal{B}_{38}^{(1)}$ into two classes of~size~$211$. For~each seed~$u$ in the~first class, $u$ ends in~$\textcolor{purple!69!black}{\mathtt{22}}$, both its multiplicities are odd, the~residual~$\textcolor{purple!69!black}{\mathtt{12}}$ is reachable after~$u$, and
\begin{align}\label{eq:C1-pump-one}
 \textcolor{purple!69!black}{\mathtt{12}}\xrightarrow{\textcolor{purple!69!black}{\mathtt{1122}}}\textcolor{purple!69!black}{\mathtt{12}},
 \qquad \textcolor{purple!69!black}{\mathtt{12}}\xrightarrow{\textcolor{purple!69!black}{\mathtt{12}}}\varepsilon,
 \qquad \textcolor{purple!69!black}{\mathtt{12}}\xrightarrow{\textcolor{purple!69!black}{\mathtt{1121}}}\varepsilon.
\end{align}
For~each seed in~the~second class, the~complementary assertions hold: $u$ ends in~$\textcolor{purple!69!black}{\mathtt{11}}$, residual~$\textcolor{purple!69!black}{\mathtt{21}}$ is reachable, and
\begin{align}\label{eq:C1-pump-two}
 \textcolor{purple!69!black}{\mathtt{21}}\xrightarrow{\textcolor{purple!69!black}{\mathtt{2211}}}\textcolor{purple!69!black}{\mathtt{21}},
 \qquad \textcolor{purple!69!black}{\mathtt{21}}\xrightarrow{\textcolor{purple!69!black}{\mathtt{21}}}\varepsilon,
 \qquad \textcolor{purple!69!black}{\mathtt{21}}\xrightarrow{\textcolor{purple!69!black}{\mathtt{2212}}}\varepsilon.
\end{align}

For~a~concrete illustration, consider the~seed
\begin{align*}
 U=\textcolor{purple!69!black}{\mathtt{12}}(\textcolor{purple!69!black}{\mathtt{1122}})^9\in\mathcal{B}_{38}^{(1)}.
\end{align*}
It contains $19$ copies of~each letter and reaches residual~$\textcolor{purple!69!black}{\mathtt{12}}$. Appending two periods and then the~exit word~$\textcolor{purple!69!black}{\mathtt{12}}$ gives the~sequence of~transitions
\begin{align*}
 \varepsilon\xrightarrow{U}\textcolor{purple!69!black}{\mathtt{12}}
 \xrightarrow{\textcolor{purple!69!black}{\mathtt{1122}}}\textcolor{purple!69!black}{\mathtt{12}}
 \xrightarrow{\textcolor{purple!69!black}{\mathtt{1122}}}\textcolor{purple!69!black}{\mathtt{12}}
 \xrightarrow{\textcolor{purple!69!black}{\mathtt{12}}}\varepsilon.
\end{align*}
Consequently, the~word
\begin{align*}
 W=U(\textcolor{purple!69!black}{\mathtt{1122}})^2\textcolor{purple!69!black}{\mathtt{12}}
   =\textcolor{purple!69!black}{\mathtt{12}}(\textcolor{purple!69!black}{\mathtt{1122}})^{11}\textcolor{purple!69!black}{\mathtt{12}}
\end{align*}
is a~shuffle square of~length~$48$, with root~$(\textcolor{purple!69!black}{\mathtt{12}})^{12}$. An~explicit decomposition assigns the~initial~$\textcolor{purple!69!black}{\mathtt{12}}$ to~the~first copy, the~first and third positions of~each block~$\textcolor{purple!69!black}{\mathtt{1122}}$ to~the~first copy, the~second and fourth positions to~the~second copy, and the~final~$\textcolor{purple!69!black}{\mathtt{12}}$ to~the~second copy. After~$U$ and after each appended period, the~first partial copy exceeds the~second by~the~same suffix~$\textcolor{purple!69!black}{\mathtt{12}}$; the~exit word supplies precisely this missing suffix.

Returning to~the~general argument, consider any seed~$u$ in~the~first class. The~$C^1$ condition forces the~next letter after~$\textcolor{purple!69!black}{\mathtt{22}}$ to~be~$\textcolor{purple!69!black}{\mathtt{1}}$. Choosing~$\textcolor{purple!69!black}{\mathtt{2}}$ next completes the~exit word~$\textcolor{purple!69!black}{\mathtt{12}}$ and hence a~shuffle-square prefix by~\eqref{eq:C1-pump-one}. Choosing $\textcolor{purple!69!black}{\mathtt{1}}$ is therefore the~only bad continuation. The~next letter is then forced to~be~$\textcolor{purple!69!black}{\mathtt{2}}$. Choosing~$\textcolor{purple!69!black}{\mathtt{1}}$ after it completes the~other exit $\textcolor{purple!69!black}{\mathtt{1121}}$ and gives a~shuffle-square prefix. Hence the~unique bad four-letter continuation is~$\textcolor{purple!69!black}{\mathtt{1122}}$. This block returns both the~last run and the~reachable residual to~their initial states. Induction makes $u(\textcolor{purple!69!black}{\mathtt{1122}})^\omega$ the~unique bad ray from~$u$. Every finite prefix along this ray has at least one odd multiplicity, while each block endpoint has both multiplicities odd, so no full word on the~ray is itself a~shuffle square. The~same argument with~\eqref{eq:C1-pump-two} gives the unique ray $u(\textcolor{purple!69!black}{\mathtt{2211}})^\omega$ from every seed in~the~second class. Thus $|\mathcal{B}_n^{(1)}|=422$ for~every $n\geqslant38$, and none of~these words has even Parikh vector.

It follows from Table~\ref{tab:C1-even-bad} that an~even-Parikh $C^1$-word of~length at least~$36$ with no shuffle-square prefix does not exist. A~non-shuffle-square word satisfying the~hypotheses must therefore have a~proper such prefix. Applying the~same conclusion to $\operatorname{rev}(w)$ and using reversal closure gives the~suffix. Finally, \begin{align}\label{eq:C1-sharp34}
 \textcolor{purple!69!black}{\mathtt{1221121121221221212211221122112212}}
 =\textcolor{purple!69!black}{\mathtt{122}}(\textcolor{purple!69!black}{\mathtt{112}})^2(\textcolor{purple!69!black}{\mathtt{122}})^2\textcolor{purple!69!black}{\mathtt{12}}(\textcolor{purple!69!black}{\mathtt{1221}})^4\textcolor{purple!69!black}{\mathtt{2}}
\end{align}
has length~$34$, even Parikh vector, and belongs to $\mathcal{B}_{34}^{(1)}$, proving the~sharpness assertion.

Listing~\ref{lst:C1-verification} records all finite assertions needed for the~count, the~pumping step, and the~example establishing sharpness.

