The~recurrence, complete level vector, Table~\ref{tab:C1-even-bad}, transition identities \eqref{eq:C1-pump-one}--\eqref{eq:C1-pump-two}, and Listing~\ref{lst:C1-verification} together give a~finite verification independent of supplementary source code.

\label{cor:C1-factorization}
Every nonempty even-Parikh $C^1$-word~$w$ has a~greedy factorization
\begin{align*}
 w=S_1S_2\cdots S_k r,
\end{align*}
where every $S_i$ is a~$C^1$ shuffle square and the~terminal remainder is either empty or one of~the~$230$ words counted in Table~\ref{tab:C1-even-bad}. In~particular, $|r|\leqslant34$. If $w$ is not a~shuffle square, then $r\ne\varepsilon$. There is no uniform upper bound on the~lengths of~the~blocks~$S_i$.

\label{ex:odd-ABBA-reduction}
Consider the~odd members of~the~family $W_n=(\textcolor{purple!69!black}{\mathtt{2112}})^n$ introduced above. Grytczuk, Pawlik, and Ruci\'nski proved that none of~these words is a~shuffle square~\cite{GrytczukPawlikRucinskiPreprint}. Put
\begin{align*}
  S=(\textcolor{purple!69!black}{\mathtt{2112}})^2=\textcolor{purple!69!black}{\mathtt{21122112}}.
\end{align*}
For~$j\geqslant1$, we have $W_{2j+1}=S W_{2j-1}$. The~word~$S$ is an~ordinary square and hence a~shuffle square. It is the~shortest nonempty shuffle-square prefix: the~prefixes of~lengths~$2$ and~$6$ have odd letter multiplicities, while the~length-$4$ prefix is~$\textcolor{purple!69!black}{\mathtt{2112}}$, the~complement of~the~obstruction in~Example~\ref{ex:1221}. The~greedy factorization therefore removes~$S$ exactly~$j$ times and leaves~$W_1=\textcolor{purple!69!black}{\mathtt{2112}}$. Thus this infinite family of~$C^1$ exceptions reduces to~a~single irreducible word of~length~$4$.

\label{thm:finite-factorization}
Every finite $C^3$-word~$w$ has a~factorization
\begin{align*}
  w=S_1S_2\cdots S_k r,
\end{align*}
obtained by~repeatedly removing the~shortest nonempty shuffle-square prefix. Here
\begin{enumerate}[(i)]
\item each $S_i$ is a~$C^3$ shuffle square and $2\leqslant|S_i|\leqslant24$.
\item the~terminal remainder~$r$ belongs to~$\mathcal{C}^3$, has no nonempty shuffle-square prefix, satisfies $r\in\mathcal{B}_{|r|}^{(3)}$, and has $|r|\leqslant23$.
\item $S_1\cdots S_k$ is a~shuffle square whenever $k\geqslant1$.
\end{enumerate}
If $w\in\mathcal{C}^h$ for~some $h\geqslant3$, then all blocks and the~remainder belong to~$\mathcal{C}^h$. If $w$ is smooth, they are smooth. In~particular, every $C^3$-word of~length~$n\geqslant24$ has a~shuffle-square prefix and suffix of~length at~least $n-23$.

\label{ex:greedy-P20}
For~the~smooth word $P_{20}$, Theorem~\ref{thm:main-intro} shows that the~shortest shuffle-square prefix is $P_{16}$, and the~greedy factorization is
\begin{align*}
  P_{20}=P_{16}\,\textcolor{purple!69!black}{\mathtt{1221}}.
\end{align*}
The~remainder $\textcolor{purple!69!black}{\mathtt{1221}}$ has no nonempty shuffle-square prefix, by~Example~\ref{ex:1221}.  Nevertheless, $P_{20}$ itself is a~shuffle square, as~Table~\ref{tab:base} shows.  Thus Theorem~\ref{thm:finite-factorization} is a~canonical bounded-block construction, not a~claim that its terminal remainder characterizes whether the~original word is a~shuffle square.

\label{thm:infinite-factorization}
Let $X=X_1X_2\cdots$ be a~length-$24$ locally~$C^3$ right-infinite word, and fix a~starting position $t\geqslant1$.  Put $s_0=t-1$.  Recursively, let $d_k$ be the~least positive integer~$d$ for~which
\begin{align*}
  X_{s_{k-1}+1}X_{s_{k-1}+2}\cdots X_{s_{k-1}+d}
\end{align*}
is a~shuffle square, and put $s_k=s_{k-1}+d_k$.  Then the~recursion is defined for~all $k\geqslant1$ and
\begin{align*}
  2\leqslant d_k\leqslant24.
\end{align*}
Every cumulative factor $X_tX_{t+1}\cdots X_{s_k}$ is a~shuffle square. Moreover, if
\begin{align*}
 A_{X,t}(N)=\#\{1\leqslant\ell\leqslant N:
 X_tX_{t+1}\cdots X_{t+\ell-1}\text{ is a~shuffle square}\},
\end{align*}
then
\begin{align}\label{eq:local-density}
  \left\lfloor\frac{N}{24}\right\rfloor
  \leqslant A_{X,t}(N)\leqslant\left\lfloor\frac{N}{2}\right\rfloor
  \qquad(N\geqslant1),
\end{align}
and hence
\begin{align*}
  \frac1{24}
  \leqslant\liminf_{N\to\infty}\frac{A_{X,t}(N)}{N}
  \leqslant\limsup_{N\to\infty}\frac{A_{X,t}(N)}{N}
  \leqslant\frac12.
\end{align*}

\label{cor:bi-infinite}
Let $X=(X_i)_{i\in\mathbb Z}$ be a~length-$24$ locally~$C^3$ bi-infinite word, and fix any cut $c_0\in\mathbb Z$.  There is a~strictly increasing sequence of~cuts $(c_k)_{k\in\mathbb Z}$ such that
\begin{align*}
  2\leqslant c_{k+1}-c_k\leqslant24
\end{align*}
and every block $X_{c_k+1}\cdots X_{c_{k+1}}$ is a~shuffle square.

\label{cor:kolakoski-density}
The~increasing enumeration of~$\operatorname{EPK}\setminus\{4,8\}$, equivalently the~sequence of~shuffle-square prefix lengths of~$\textcolor{purple!69!black}{\boldsymbol{\mathsf{K}}}$, begins
\begin{align*}
  16,20,24,28,34,36,40,44,48,56,60,64,66,68,72,76,80,\ldots.
\end{align*}
It is infinite, and consecutive terms differ by~one of~$2,4,6,8$. If
\begin{align*}
  H_{\textcolor{purple!69!black}{\boldsymbol{\mathsf{K}}}}(N)=\#\{1\leqslant m\leqslant N:P_m\text{ is a~shuffle square}\},
\end{align*}
then, for~every $N\geqslant16$,
\begin{align}\label{eq:K-density}
  H_{\textcolor{purple!69!black}{\boldsymbol{\mathsf{K}}}}(N)\geqslant
  1+\left\lfloor\frac{N-16}{8}\right\rfloor,
\end{align}
and consequently
\begin{align*}
  \liminf_{N\to\infty}\frac{H_{\textcolor{purple!69!black}{\boldsymbol{\mathsf{K}}}}(N)}N\geqslant\frac18.
\end{align*}

\label{cor:constructed-subsequence}
Put $s_0=0$.  Once $s_{k-1}$ is defined, let $d_k$ be the~least positive integer~$d$ for~which
\begin{align*}
  \textcolor{purple!69!black}{\boldsymbol{\mathsf{K}}}_{s_{k-1}+1}\textcolor{purple!69!black}{\boldsymbol{\mathsf{K}}}_{s_{k-1}+2}\cdots\textcolor{purple!69!black}{\boldsymbol{\mathsf{K}}}_{s_{k-1}+d}
\end{align*}
is a~shuffle square, and put $s_k=s_{k-1}+d_k$.  This recursion is well-defined for~every $k\geqslant1$, and
\begin{align*}
  2\leqslant d_k\leqslant24.
\end{align*}
Every $P_{s_k}$ is a~shuffle square.  The~initial cumulative endpoints are
\begin{align*}
  16,34,36,48,56,66,68,88,90,104,110,116,124,134,136,\ldots.
\end{align*}
They form an~infinite proper subsequence of~the~increasing enumeration of~$\operatorname{EPK}\setminus\{4,8\}$.  The~omitted terms, such as~$20,24,28,40$, are shuffle-square prefixes but are not endpoints of~that particular recursive factorization.

